INSERT INTO task_type_template (type_id, locale, render_target, template_text, spec_version)
VALUES
    ('G9-GEO-004', 'ru-KZ', 'plaintext', 'По теореме косинусов найдите сторону c: c² = {{a}}² + {{b}}² − 2·{{a}}·{{b}}·cos({{C}}°).', '1.0.0-draft'),
    ('G9-GEO-005', 'ru-KZ', 'plaintext', 'Найдите площадь треугольника по формуле S = ½ab·sin(C), если a = {{a}}, b = {{b}}, C = {{C}}°.', '1.0.0-draft'),
    ('G9-GEO-006', 'ru-KZ', 'plaintext', 'Вписанный угол равен {{angle}}°. Найдите градусную меру дуги, на которую он опирается.', '1.0.0-draft'),
    ('G9-GEO-007', 'ru-KZ', 'plaintext', 'Хорда окружности радиуса {{r}} находится на расстоянии {{d}} от центра. Найдите длину хорды.', '1.0.0-draft'),
    ('G9-GEO-008', 'ru-KZ', 'plaintext', 'Радиус окружности равен {{r}}, а градусная мера центрального угла — {{angle}}°. Найдите длину соответствующей дуги.', '1.0.0-draft'),
    ('G9-GEO-009', 'ru-KZ', 'plaintext', 'Радиус окружности равен {{r}}, а градусная мера центрального угла — {{angle}}°. Найдите площадь соответствующего сектора.', '1.0.0-draft'),
    ('G9-GEO-010', 'ru-KZ', 'plaintext', 'Запишите уравнение окружности с центром ({{h}}; {{k}}) и радиусом {{r}}.', '1.0.0-draft'),
    ('G9-PRO-001', 'ru-KZ', 'plaintext', 'В гардеробе есть {{shirts}} рубашек и {{pants}} пар брюк. Сколько различных комплектов одежды можно составить, выбрав по одному предмету каждого вида?', '1.0.0-draft'),
    ('G9-STA-003', 'ru-KZ', 'plaintext', 'В таблице сопряжённости четыре значения: {{a}}, {{b}}, {{c}} и {{d}}. Найдите их общую сумму.', '1.0.0-draft'),
    ('G9-STA-004', 'ru-KZ', 'plaintext', 'Относительная частота события составляет {{a}} случаев из {{b}} наблюдений. Найдите относительную частоту в виде десятичной дроби.', '1.0.0-draft')
